import React, {
  useEffect,
  useRef,
  useState,
} from 'react';

import { toast } from 'react-toastify';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiImage,
  FiHome,
  FiCheckCircle,
  FiGlobe,
} from 'react-icons/fi';

import api, {
  getApiErrorMessage,
} from '../../services/api';

import {
  getImageUrl,
} from '../../utils/helpers';

import {
  useLanguage,
} from '../../contexts/LanguageContext';

import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';


const DEFAULT_IMG = '/default-avatar.png';


const initialForm = {
  name_en: '',
  name_km: '',
  acronym: '',
  tag_en: '',
  tag_km: '',
  description_en: '',
  description_km: '',
  features_en: '',
  features_km: '',
  is_active: true,
  order: 0,
};


const AdminSchools = () => {

  const {
    t,
    language,
  } = useLanguage();


  const [schools, setSchools] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingSchool, setEditingSchool] = useState(null);

  const [formData, setFormData] = useState({
    ...initialForm,
  });

  const [imageFile, setImageFile] = useState(null);
  const [submitting, setSubmitting] = useState(false);

  const fileRef = useRef(null);


  const isKhmer =
    language === 'km' ||
    language === 'kh';


  const tr = (
    key,
    englishFallback,
    khmerFallback
  ) => {

    const value = t(key);

    if (
      value &&
      value !== key
    ) {
      return value;
    }

    return isKhmer
      ? khmerFallback
      : englishFallback;
  };


  const getSchoolName = (school) => {

    if (!school) {
      return '-';
    }

    if (isKhmer) {
      return (
        school.name_km ||
        school.name_en ||
        '-'
      );
    }

    return (
      school.name_en ||
      school.name_km ||
      '-'
    );
  };


  const getSchoolTag = (school) => {

    if (!school) {
      return '-';
    }

    if (isKhmer) {
      return (
        school.tag_km ||
        school.tag_en ||
        '-'
      );
    }

    return (
      school.tag_en ||
      school.tag_km ||
      '-'
    );
  };


  useEffect(() => {

    fetchSchools();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);


  const fetchSchools = async () => {

    try {

      setLoading(true);

      const response = await api.get(
        '/api/schools/'
      );

      setSchools(
        Array.isArray(response.data)
          ? response.data
          : []
      );

    } catch (error) {

      console.error(
        'Fetch schools error:',
        error
      );

      toast.error(
        getApiErrorMessage(
          error,
          tr(
            'schools.loadFailed',
            'Failed to load schools.',
            'មិនអាចទាញយកទិន្នន័យសាលាបានទេ។'
          )
        )
      );

    } finally {

      setLoading(false);
    }
  };


  const resetForm = () => {

    setEditingSchool(null);

    setFormData({
      ...initialForm,
    });

    setImageFile(null);
    setSubmitting(false);

    if (fileRef.current) {
      fileRef.current.value = '';
    }
  };


  const openCreateModal = () => {

    resetForm();
    setModalOpen(true);
  };


  const closeModal = () => {

    if (submitting) {
      return;
    }

    setModalOpen(false);
    resetForm();
  };


  const handleInputChange = (event) => {

    const {
      name,
      value,
      type,
      checked,
    } = event.target;

    setFormData(
      (previous) => ({
        ...previous,

        [name]:
          type === 'checkbox'
            ? checked
            : value,
      })
    );
  };


  const handleImageChange = (event) => {

    const file =
      event.target.files?.[0];

    if (!file) {
      setImageFile(null);
      return;
    }

    const allowedTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
    ];

    if (
      !allowedTypes.includes(file.type)
    ) {

      toast.error(
        tr(
          'schools.invalidImage',
          'Please select a JPG, JPEG, PNG or WEBP image.',
          'សូមជ្រើសរើសរូបភាពប្រភេទ JPG, JPEG, PNG ឬ WEBP។'
        )
      );

      event.target.value = '';
      setImageFile(null);

      return;
    }

    if (
      file.size >
      5 * 1024 * 1024
    ) {

      toast.error(
        tr(
          'schools.imageTooLarge',
          'Image must be 5 MB or smaller.',
          'រូបភាពត្រូវមានទំហំ 5 MB ឬតូចជាងនេះ។'
        )
      );

      event.target.value = '';
      setImageFile(null);

      return;
    }

    setImageFile(file);
  };


  const handleEdit = (school) => {

    setEditingSchool(school);

    setFormData({

      name_en:
        school.name_en || '',

      name_km:
        school.name_km || '',

      acronym:
        school.acronym || '',

      tag_en:
        school.tag_en || '',

      tag_km:
        school.tag_km || '',

      description_en:
        school.description_en || '',

      description_km:
        school.description_km || '',

      features_en:
        school.features_en || '',

      features_km:
        school.features_km || '',

      is_active:
        school.is_active ?? true,

      order:
        school.order ?? 0,
    });

    setImageFile(null);

    if (fileRef.current) {
      fileRef.current.value = '';
    }

    setModalOpen(true);
  };


  const handleSubmit = async (event) => {

    event.preventDefault();

    if (
      !formData.name_en.trim()
    ) {

      toast.error(
        tr(
          'schools.nameRequired',
          'English school name is required.',
          'សូមបញ្ចូលឈ្មោះសាលាជាភាសាអង់គ្លេស។'
        )
      );

      return;
    }

    if (
      !formData.name_km.trim()
    ) {

      toast.error(
        tr(
          'schools.khmerNameRequired',
          'Khmer school name is required.',
          'សូមបញ្ចូលឈ្មោះសាលាជាភាសាខ្មែរ។'
        )
      );

      return;
    }

    try {

      setSubmitting(true);

      const payload =
        new FormData();

      payload.append(
        'name_en',
        formData.name_en.trim()
      );

      payload.append(
        'name_km',
        formData.name_km.trim()
      );

      payload.append(
        'acronym',
        formData.acronym.trim()
      );

      payload.append(
        'tag_en',
        formData.tag_en.trim()
      );

      payload.append(
        'tag_km',
        formData.tag_km.trim()
      );

      payload.append(
        'description_en',
        formData.description_en.trim()
      );

      payload.append(
        'description_km',
        formData.description_km.trim()
      );

      payload.append(
        'features_en',
        formData.features_en.trim()
      );

      payload.append(
        'features_km',
        formData.features_km.trim()
      );

      payload.append(
        'is_active',
        String(formData.is_active)
      );

      payload.append(
        'order',
        String(
          Number(formData.order) || 0
        )
      );

      if (imageFile) {
        payload.append(
          'image',
          imageFile
        );
      }

      if (editingSchool) {

        await api.put(
          `/api/schools/${editingSchool.id}`,
          payload
        );

        toast.success(
          tr(
            'schools.updatedSuccess',
            'School updated successfully.',
            'បានកែប្រែព័ត៌មានសាលាដោយជោគជ័យ។'
          )
        );

      } else {

        await api.post(
          '/api/schools/',
          payload
        );

        toast.success(
          tr(
            'schools.createdSuccess',
            'School created successfully.',
            'បានបង្កើតសាលាដោយជោគជ័យ។'
          )
        );
      }

      setModalOpen(false);
      resetForm();

      await fetchSchools();

    } catch (error) {

      console.error(
        'School operation error:',
        error
      );

      toast.error(
        getApiErrorMessage(
          error,
          tr(
            'common.operationFailed',
            'Operation failed.',
            'ប្រតិបត្តិការមិនបានជោគជ័យ។'
          )
        )
      );

    } finally {

      setSubmitting(false);
    }
  };


  const handleDelete = async (schoolId) => {

    const confirmed =
      window.confirm(
        tr(
          'schools.deleteConfirm',
          'Are you sure you want to delete this school?',
          'តើអ្នកប្រាកដថាចង់លុបសាលានេះមែនទេ?'
        )
      );

    if (!confirmed) {
      return;
    }

    try {

      await api.delete(
        `/api/schools/${schoolId}`
      );

      toast.success(
        tr(
          'schools.deletedSuccess',
          'School deleted successfully.',
          'បានលុបសាលាដោយជោគជ័យ។'
        )
      );

      await fetchSchools();

    } catch (error) {

      console.error(
        'Delete school error:',
        error
      );

      toast.error(
        getApiErrorMessage(
          error,
          tr(
            'schools.deleteFailed',
            'Failed to delete school.',
            'មិនអាចលុបសាលាបានទេ។'
          )
        )
      );
    }
  };


  const columns = [

    {
      key: 'image',

      label: tr(
        'schools.image',
        'Image',
        'រូបភាព'
      ),

      render: (value) => (

        <div
          className="
            w-20
            h-14
            rounded-xl
            overflow-hidden
            border
            border-blue-200
            bg-blue-50
            shadow-sm
          "
        >

          <img
            src={
              getImageUrl(
                value,
                DEFAULT_IMG
              )
            }

            alt={
              tr(
                'schools.image',
                'School image',
                'រូបភាពសាលា'
              )
            }

            className="
              w-full
              h-full
              object-cover
            "

            onError={(event) => {
              event.currentTarget.src =
                DEFAULT_IMG;
            }}
          />

        </div>
      ),
    },


    {
      key: 'acronym',

      label: tr(
        'schools.acronym',
        'Acronym',
        'អក្សរកាត់'
      ),

      render: (value) => (

        <span
          className="
            inline-flex
            items-center
            justify-center
            min-w-[52px]
            px-3
            py-1.5
            rounded-lg
            bg-blue-50
            text-blue-900
            border
            border-blue-200
            text-xs
            font-bold
          "
        >
          {value || '-'}
        </span>
      ),
    },


    {
      key: 'name_en',

      label: tr(
        'schools.schoolName',
        'School Name',
        'ឈ្មោះសាលា'
      ),

      render: (
        value,
        row
      ) => (

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-9
              h-9
              flex
              items-center
              justify-center
              rounded-lg
              bg-blue-50
              text-blue-900
              flex-shrink-0
            "
          >

            <FiHome size={17} />

          </div>


          <div className="min-w-0">

            <p
              className="
                font-semibold
                text-blue-900
                truncate
              "
            >
              {getSchoolName(row)}
            </p>


            {
              row.name_en &&
              row.name_km && (

                <p
                  className="
                    text-xs
                    text-blue-300
                    mt-0.5
                    truncate
                  "
                >
                  {
                    isKhmer
                      ? row.name_en
                      : row.name_km
                  }
                </p>
              )
            }

          </div>

        </div>
      ),
    },


    {
      key: 'tag_en',

      label: tr(
        'schools.tag',
        'Tag',
        'ស្លាក'
      ),

      render: (
        value,
        row
      ) => (

        <span
          className="
            inline-flex
            px-3
            py-1.5
            rounded-full
            bg-blue-50
            text-blue-500
            text-xs
            font-medium
          "
        >
          {getSchoolTag(row)}
        </span>
      ),
    },


    {
      key: 'order',

      label: tr(
        'schools.order',
        'Order',
        'លំដាប់'
      ),

      render: (value) => (

        <span
          className="
            inline-flex
            items-center
            justify-center
            w-8
            h-8
            rounded-lg
            bg-blue-50
            text-blue-900
            font-semibold
            text-xs
          "
        >
          {value ?? 0}
        </span>
      ),
    },


    {
      key: 'is_active',

      label: tr(
        'schools.status',
        'Status',
        'ស្ថានភាព'
      ),

      render: (value) => (

        <span
          className={
            value
              ? 'inline-flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-semibold border bg-green-50 text-green-700 border-green-200'
              : 'inline-flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-semibold border bg-red-50 text-red-600 border-red-200'
          }
        >

          <span
            className={
              value
                ? 'w-2 h-2 rounded-full bg-green-500'
                : 'w-2 h-2 rounded-full bg-red-500'
            }
          />


          {
            value
              ? tr(
                  'schools.active',
                  'Active',
                  'សកម្ម'
                )
              : tr(
                  'schools.inactive',
                  'Inactive',
                  'អសកម្ម'
                )
          }

        </span>
      ),
    },


    {
      key: 'actions',

      label: tr(
        'common.actions',
        'Actions',
        'សកម្មភាព'
      ),

      render: (
        value,
        row
      ) => (

        <div
          className="
            flex
            items-center
            gap-2
          "
        >

          <button
            type="button"

            onClick={() =>
              handleEdit(row)
            }

            title={
              tr(
                'common.edit',
                'Edit',
                'កែប្រែ'
              )
            }

            className="
              w-9
              h-9
              flex
              items-center
              justify-center
              rounded-lg
              bg-blue-50
              text-blue-900
              hover:bg-blue-900
              hover:text-white
              transition-all
              duration-200
            "
          >
            <FiEdit2 size={16} />
          </button>


          <button
            type="button"

            onClick={() =>
              handleDelete(row.id)
            }

            title={
              tr(
                'common.delete',
                'Delete',
                'លុប'
              )
            }

            className="
              w-9
              h-9
              flex
              items-center
              justify-center
              rounded-lg
              bg-red-50
              text-red-600
              hover:bg-red-600
              hover:text-white
              transition-all
              duration-200
            "
          >
            <FiTrash2 size={16} />
          </button>

        </div>
      ),
    },
  ];


  return (

    <div
      className={
        isKhmer
          ? 'w-full font-khmer'
          : 'w-full font-english'
      }
    >

      <div
        className="
          flex
          flex-col
          sm:flex-row
          sm:items-center
          sm:justify-between
          gap-4
          mb-7
        "
      >

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-12
              h-12
              flex
              items-center
              justify-center
              rounded-xl
              bg-blue-900
              text-white
              shadow-sm
              flex-shrink-0
            "
          >
            <FiHome size={22} />
          </div>


          <div>

            <h1
              className="
                text-2xl
                sm:text-3xl
                font-bold
                text-blue-900
                leading-tight
              "
            >
              {
                tr(
                  'schools.title',
                  'Schools Management',
                  'គ្រប់គ្រងសាលា'
                )
              }
            </h1>


            <p
              className="
                text-sm
                text-blue-400
                mt-1
              "
            >
              {
                tr(
                  'schools.subtitle',
                  'Manage school information and bilingual content',
                  'គ្រប់គ្រងព័ត៌មានសាលា និងមាតិកាជាភាសាខ្មែរ និងអង់គ្លេស'
                )
              }
            </p>

          </div>

        </div>


        <button
          type="button"

          onClick={
            openCreateModal
          }

          className="
            inline-flex
            items-center
            justify-center
            gap-2
            h-11
            px-5
            bg-red-600
            hover:bg-red-700
            text-white
            rounded-xl
            text-sm
            font-semibold
            shadow-sm
            hover:shadow-md
            transition-all
            duration-200
          "
        >

          <FiPlus size={18} />

          {
            tr(
              'schools.addSchool',
              'Add School',
              'បន្ថែមសាលា'
            )
          }

        </button>

      </div>


      <AdminCard
        className="
          overflow-hidden
          bg-white
          border
          border-blue-200
          rounded-2xl
          shadow-sm
        "
      >

        <AdminTable
          columns={columns}
          data={schools}
          loading={loading}
        />

      </AdminCard>


      <AdminModal
        isOpen={modalOpen}

        onClose={closeModal}

        title={
          editingSchool
            ? tr(
                'schools.editSchool',
                'Edit School',
                'កែប្រែសាលា'
              )
            : tr(
                'schools.addSchool',
                'Add School',
                'បន្ថែមសាលា'
              )
        }
      >

        <form
          onSubmit={
            handleSubmit
          }
        >

          <div className="space-y-6">

            <div
              className="
                border
                border-blue-200
                rounded-2xl
                overflow-hidden
              "
            >

              <div
                className="
                  flex
                  items-center
                  gap-2
                  px-4
                  py-3
                  bg-blue-50
                  border-b
                  border-blue-200
                "
              >

                <FiGlobe
                  className="text-blue-900"
                />


                <h3
                  className="
                    font-semibold
                    text-blue-900
                  "
                >
                  {
                    tr(
                      'schools.englishContent',
                      'English Content',
                      'មាតិកាភាសាអង់គ្លេស'
                    )
                  }
                </h3>

              </div>


              <div
                className="
                  p-4
                  space-y-4
                "
              >

                <div>

                  <label className="admin-label">

                    {
                      tr(
                        'schools.englishSchoolName',
                        'English School Name',
                        'ឈ្មោះសាលាជាភាសាអង់គ្លេស'
                      )
                    }

                    <span
                      className="
                        text-red-600
                        ml-1
                      "
                    >
                      *
                    </span>

                  </label>


                  <input
                    type="text"

                    name="name_en"

                    value={
                      formData.name_en
                    }

                    onChange={
                      handleInputChange
                    }

                    className="
                      admin-input
                      font-english
                    "

                    placeholder={
                      tr(
                        'schools.englishNamePlaceholder',
                        'Enter school name in English',
                        'បញ្ចូលឈ្មោះសាលាជាភាសាអង់គ្លេស'
                      )
                    }

                    required
                  />

                </div>


                <div>

                  <label className="admin-label">
                    {
                      tr(
                        'schools.englishTag',
                        'English Tag',
                        'ស្លាកជាភាសាអង់គ្លេស'
                      )
                    }
                  </label>


                  <input
                    type="text"

                    name="tag_en"

                    value={
                      formData.tag_en
                    }

                    onChange={
                      handleInputChange
                    }

                    className="
                      admin-input
                      font-english
                    "

                    placeholder={
                      tr(
                        'schools.englishTagPlaceholder',
                        'Enter school tag in English',
                        'បញ្ចូលស្លាកសាលាជាភាសាអង់គ្លេស'
                      )
                    }
                  />

                </div>


                <div>

                  <label className="admin-label">
                    {
                      tr(
                        'schools.englishDescription',
                        'English Description',
                        'ការពិពណ៌នាជាភាសាអង់គ្លេស'
                      )
                    }
                  </label>


                  <textarea
                    name="description_en"

                    value={
                      formData.description_en
                    }

                    onChange={
                      handleInputChange
                    }

                    rows="4"

                    className="
                      admin-input
                      resize-none
                      font-english
                    "

                    placeholder={
                      tr(
                        'schools.englishDescriptionPlaceholder',
                        'Enter school description in English',
                        'បញ្ចូលការពិពណ៌នាសាលាជាភាសាអង់គ្លេស'
                      )
                    }
                  />

                </div>


                <div>

                  <label className="admin-label">
                    {
                      tr(
                        'schools.englishFeatures',
                        'English Features',
                        'លក្ខណៈពិសេសជាភាសាអង់គ្លេស'
                      )
                    }
                  </label>


                  <textarea
                    name="features_en"

                    value={
                      formData.features_en
                    }

                    onChange={
                      handleInputChange
                    }

                    rows="3"

                    className="
                      admin-input
                      resize-none
                      font-english
                    "

                    placeholder={
                      tr(
                        'schools.englishFeaturesPlaceholder',
                        'Enter school features in English',
                        'បញ្ចូលលក្ខណៈពិសេសរបស់សាលាជាភាសាអង់គ្លេស'
                      )
                    }
                  />

                </div>

              </div>

            </div>


            <div
              className="
                border
                border-blue-200
                rounded-2xl
                overflow-hidden
              "
            >

              <div
                className="
                  flex
                  items-center
                  gap-2
                  px-4
                  py-3
                  bg-blue-50
                  border-b
                  border-blue-200
                "
              >

                <FiGlobe
                  className="text-blue-900"
                />


                <h3
                  className="
                    font-semibold
                    text-blue-900
                  "
                >
                  {
                    tr(
                      'schools.khmerContent',
                      'Khmer Content',
                      'មាតិកាភាសាខ្មែរ'
                    )
                  }
                </h3>

              </div>


              <div
                className="
                  p-4
                  space-y-4
                "
              >

                <div>

                  <label className="admin-label">

                    {
                      tr(
                        'schools.khmerSchoolName',
                        'Khmer School Name',
                        'ឈ្មោះសាលាជាភាសាខ្មែរ'
                      )
                    }

                    <span
                      className="
                        text-red-600
                        ml-1
                      "
                    >
                      *
                    </span>

                  </label>


                  <input
                    type="text"

                    name="name_km"

                    value={
                      formData.name_km
                    }

                    onChange={
                      handleInputChange
                    }

                    className="
                      admin-input
                      font-khmer
                    "

                    placeholder={
                      tr(
                        'schools.khmerNamePlaceholder',
                        'Enter school name in Khmer',
                        'បញ្ចូលឈ្មោះសាលាជាភាសាខ្មែរ'
                      )
                    }

                    required
                  />

                </div>


                <div>

                  <label className="admin-label">
                    {
                      tr(
                        'schools.khmerTag',
                        'Khmer Tag',
                        'ស្លាកជាភាសាខ្មែរ'
                      )
                    }
                  </label>


                  <input
                    type="text"

                    name="tag_km"

                    value={
                      formData.tag_km
                    }

                    onChange={
                      handleInputChange
                    }

                    className="
                      admin-input
                      font-khmer
                    "

                    placeholder={
                      tr(
                        'schools.khmerTagPlaceholder',
                        'Enter school tag in Khmer',
                        'បញ្ចូលស្លាកសាលាជាភាសាខ្មែរ'
                      )
                    }
                  />

                </div>


                <div>

                  <label className="admin-label">
                    {
                      tr(
                        'schools.khmerDescription',
                        'Khmer Description',
                        'ការពិពណ៌នាជាភាសាខ្មែរ'
                      )
                    }
                  </label>


                  <textarea
                    name="description_km"

                    value={
                      formData.description_km
                    }

                    onChange={
                      handleInputChange
                    }

                    rows="4"

                    className="
                      admin-input
                      resize-none
                      font-khmer
                    "

                    placeholder={
                      tr(
                        'schools.khmerDescriptionPlaceholder',
                        'Enter school description in Khmer',
                        'បញ្ចូលការពិពណ៌នាសាលាជាភាសាខ្មែរ'
                      )
                    }
                  />

                </div>


                <div>

                  <label className="admin-label">
                    {
                      tr(
                        'schools.khmerFeatures',
                        'Khmer Features',
                        'លក្ខណៈពិសេសជាភាសាខ្មែរ'
                      )
                    }
                  </label>


                  <textarea
                    name="features_km"

                    value={
                      formData.features_km
                    }

                    onChange={
                      handleInputChange
                    }

                    rows="3"

                    className="
                      admin-input
                      resize-none
                      font-khmer
                    "

                    placeholder={
                      tr(
                        'schools.khmerFeaturesPlaceholder',
                        'Enter school features in Khmer',
                        'បញ្ចូលលក្ខណៈពិសេសរបស់សាលាជាភាសាខ្មែរ'
                      )
                    }
                  />

                </div>

              </div>

            </div>


            <div
              className="
                border
                border-blue-200
                rounded-2xl
                overflow-hidden
              "
            >

              <div
                className="
                  px-4
                  py-3
                  bg-blue-50
                  border-b
                  border-blue-200
                "
              >

                <h3
                  className="
                    font-semibold
                    text-blue-900
                  "
                >
                  {
                    tr(
                      'common.generalInformation',
                      'General Information',
                      'ព័ត៌មានទូទៅ'
                    )
                  }
                </h3>

              </div>


              <div
                className="
                  p-4
                  space-y-5
                "
              >

                <div
                  className="
                    grid
                    grid-cols-1
                    md:grid-cols-2
                    gap-4
                  "
                >

                  <div>

                    <label className="admin-label">
                      {
                        tr(
                          'schools.acronym',
                          'Acronym',
                          'អក្សរកាត់'
                        )
                      }
                    </label>


                    <input
                      type="text"

                      name="acronym"

                      value={
                        formData.acronym
                      }

                      onChange={
                        handleInputChange
                      }

                      className="admin-input"

                      placeholder={
                        tr(
                          'schools.acronymPlaceholder',
                          'Example: SC',
                          'ឧទាហរណ៍៖ SC'
                        )
                      }
                    />

                  </div>


                  <div>

                    <label className="admin-label">
                      {
                        tr(
                          'schools.order',
                          'Display Order',
                          'លំដាប់បង្ហាញ'
                        )
                      }
                    </label>


                    <input
                      type="number"

                      name="order"

                      min="0"

                      value={
                        formData.order
                      }

                      onChange={
                        handleInputChange
                      }

                      className="admin-input"
                    />

                  </div>

                </div>


                <div>

                  <label className="admin-label">
                    {
                      tr(
                        'schools.schoolImage',
                        'School Image',
                        'រូបភាពសាលា'
                      )
                    }
                  </label>


                  <div
                    onClick={() => {

                      if (fileRef.current) {
                        fileRef.current.click();
                      }

                    }}

                    className="
                      group
                      border-2
                      border-dashed
                      border-blue-200
                      hover:border-blue-900
                      bg-blue-50
                      rounded-2xl
                      px-5
                      py-7
                      text-center
                      cursor-pointer
                      transition-all
                      duration-200
                    "
                  >

                    <input
                      ref={fileRef}

                      type="file"

                      accept="
                        image/jpeg,
                        image/jpg,
                        image/png,
                        image/webp
                      "

                      onChange={
                        handleImageChange
                      }

                      className="hidden"
                    />


                    {
                      imageFile ? (

                        <div>

                          <div
                            className="
                              w-14
                              h-14
                              mx-auto
                              mb-3
                              flex
                              items-center
                              justify-center
                              rounded-xl
                              bg-white
                              text-blue-900
                              border
                              border-blue-200
                            "
                          >

                            <FiImage size={25} />

                          </div>


                          <p
                            className="
                              text-sm
                              font-semibold
                              text-blue-900
                              break-all
                            "
                          >
                            {imageFile.name}
                          </p>


                          <p
                            className="
                              text-xs
                              text-blue-400
                              mt-1
                            "
                          >
                            {
                              tr(
                                'schools.changeImage',
                                'Click to choose another image',
                                'ចុចដើម្បីជ្រើសរើសរូបភាពផ្សេង'
                              )
                            }
                          </p>

                        </div>

                      ) : (

                        <div>

                          {
                            editingSchool &&
                            editingSchool.image ? (

                              <>

                                <img
                                  src={
                                    getImageUrl(
                                      editingSchool.image,
                                      DEFAULT_IMG
                                    )
                                  }

                                  alt={
                                    tr(
                                      'schools.image',
                                      'School image',
                                      'រូបភាពសាលា'
                                    )
                                  }

                                  className="
                                    w-28
                                    h-20
                                    mx-auto
                                    mb-3
                                    object-cover
                                    rounded-xl
                                    border
                                    border-blue-200
                                  "

                                  onError={(event) => {
                                    event.currentTarget.src =
                                      DEFAULT_IMG;
                                  }}
                                />


                                <div
                                  className="
                                    inline-flex
                                    items-center
                                    gap-1.5
                                    px-3
                                    py-1.5
                                    rounded-full
                                    bg-white
                                    text-blue-900
                                    border
                                    border-blue-200
                                    text-xs
                                    font-medium
                                  "
                                >

                                  <FiCheckCircle />

                                  {
                                    tr(
                                      'schools.currentImage',
                                      'Current image',
                                      'រូបភាពបច្ចុប្បន្ន'
                                    )
                                  }

                                </div>


                                <p
                                  className="
                                    text-xs
                                    text-blue-400
                                    mt-2
                                  "
                                >
                                  {
                                    tr(
                                      'schools.changeImage',
                                      'Click to choose another image',
                                      'ចុចដើម្បីជ្រើសរើសរូបភាពផ្សេង'
                                    )
                                  }
                                </p>

                              </>

                            ) : (

                              <>

                                <div
                                  className="
                                    w-14
                                    h-14
                                    mx-auto
                                    mb-3
                                    flex
                                    items-center
                                    justify-center
                                    rounded-xl
                                    bg-white
                                    border
                                    border-blue-200
                                    shadow-sm
                                    text-blue-400
                                    group-hover:text-blue-900
                                    group-hover:scale-105
                                    transition-all
                                  "
                                >

                                  <FiImage size={25} />

                                </div>


                                <p
                                  className="
                                    text-sm
                                    font-semibold
                                    text-blue-900
                                  "
                                >
                                  {
                                    tr(
                                      'schools.chooseImage',
                                      'Click to upload image',
                                      'ចុចដើម្បីជ្រើសរើសរូបភាព'
                                    )
                                  }
                                </p>


                                <p
                                  className="
                                    text-xs
                                    text-blue-400
                                    mt-1
                                  "
                                >
                                  {
                                    tr(
                                      'schools.imageHint',
                                      'JPG, JPEG, PNG, WEBP — Maximum 5 MB',
                                      'JPG, JPEG, PNG, WEBP — ទំហំអតិបរមា 5 MB'
                                    )
                                  }
                                </p>

                              </>

                            )
                          }

                        </div>
                      )
                    }

                  </div>

                </div>


                <div
                  className="
                    flex
                    items-center
                    justify-between
                    gap-4
                    px-4
                    py-3.5
                    rounded-xl
                    bg-blue-50
                    border
                    border-blue-200
                  "
                >

                  <div>

                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900
                      "
                    >
                      {
                        tr(
                          'schools.status',
                          'Status',
                          'ស្ថានភាព'
                        )
                      }
                    </p>


                    <p
                      className="
                        text-xs
                        text-blue-400
                        mt-0.5
                      "
                    >
                      {
                        formData.is_active
                          ? tr(
                              'schools.active',
                              'Active',
                              'សកម្ម'
                            )
                          : tr(
                              'schools.inactive',
                              'Inactive',
                              'អសកម្ម'
                            )
                      }
                    </p>

                  </div>


                  <label
                    className="
                      relative
                      inline-flex
                      items-center
                      cursor-pointer
                      flex-shrink-0
                    "
                  >

                    <input
                      type="checkbox"

                      name="is_active"

                      checked={
                        formData.is_active
                      }

                      onChange={
                        handleInputChange
                      }

                      className="
                        sr-only
                        peer
                      "
                    />


                    <div
                      className="
                        relative
                        w-11
                        h-6
                        bg-blue-200
                        rounded-full
                        transition-colors
                        peer-checked:bg-blue-900
                        after:content-['']
                        after:absolute
                        after:top-[2px]
                        after:left-[2px]
                        after:w-5
                        after:h-5
                        after:bg-white
                        after:rounded-full
                        after:shadow-sm
                        after:transition-all
                        peer-checked:after:translate-x-full
                      "
                    />

                  </label>

                </div>

              </div>

            </div>

          </div>


          <div
            className="
              mt-7
              pt-5
              border-t
              border-blue-200
              flex
              flex-col-reverse
              sm:flex-row
              sm:items-center
              sm:justify-end
              gap-3
            "
          >

            <button
              type="button"

              onClick={
                closeModal
              }

              disabled={
                submitting
              }

              className="
                h-11
                px-5
                rounded-xl
                border
                border-blue-200
                bg-white
                text-blue-500
                text-sm
                font-semibold
                hover:bg-blue-50
                disabled:opacity-50
                disabled:cursor-not-allowed
                transition-all
                duration-200
              "
            >
              {
                tr(
                  'common.cancel',
                  'Cancel',
                  'បោះបង់'
                )
              }
            </button>


            <button
              type="submit"

              disabled={
                submitting
              }

              className="
                h-11
                inline-flex
                items-center
                justify-center
                gap-2
                px-6
                rounded-xl
                bg-red-600
                hover:bg-red-700
                text-white
                text-sm
                font-semibold
                shadow-sm
                hover:shadow-md
                disabled:opacity-60
                disabled:cursor-not-allowed
                transition-all
                duration-200
              "
            >

              {
                submitting ? (

                  <>

                    <span
                      className="
                        w-4
                        h-4
                        border-2
                        border-white/40
                        border-t-white
                        rounded-full
                        animate-spin
                      "
                    />

                    {
                      tr(
                        'common.saving',
                        'Saving...',
                        'កំពុងរក្សាទុក...'
                      )
                    }

                  </>

                ) : editingSchool ? (

                  <>

                    <FiEdit2 size={16} />

                    {
                      tr(
                        'schools.updateSchool',
                        'Update School',
                        'រក្សាទុកការកែប្រែ'
                      )
                    }

                  </>

                ) : (

                  <>

                    <FiPlus size={17} />

                    {
                      tr(
                        'schools.createSchool',
                        'Create School',
                        'បង្កើតសាលា'
                      )
                    }

                  </>

                )
              }

            </button>

          </div>

        </form>

      </AdminModal>

    </div>
  );
};


export default AdminSchools;
